import unittest

from solucao import codigo_da_letra
from solucao import letra_do_numero


class TestALetraEUmNumero(unittest.TestCase):
    def test_a_maisculo_e_65(self):
        """codigo_da_letra devolve o numero do A maisculo"""
        self.assertEqual(codigo_da_letra("A"), 65)

    def test_a_minusculo_e_97(self):
        """codigo_da_letra devolve o numero do a minusculo"""
        self.assertEqual(codigo_da_letra("a"), 97)

    def test_65_e_o_a_maisculo(self):
        """letra_do_numero devolve o A maisculo para 65"""
        self.assertEqual(letra_do_numero(65), "A")

    def test_97_e_o_a_minusculo(self):
        """letra_do_numero devolve o a minusculo para 97"""
        self.assertEqual(letra_do_numero(97), "a")

